```go
func sendWithRetry(msg *Message) error {
    backoff := 1 * time.Second
    maxBackoff := 32 * time.Second

    for {
        resp, err := sendMessage(msg)
        if err == nil {
            return nil
        }

        if resp.StatusCode == 429 {
            // Rate limited, wait and retry
            time.Sleep(backoff)
            backoff = min(backoff*2, maxBackoff)
            continue
        }

        return err
    }
}
