#[no_mangle]
pub extern "C" fn sage_verify(
    msg_ptr: *const u8,
    msg_len: usize,
    sig_ptr: *const u8,
    sig_len: usize,
) -> bool {
    // NULL 체크 및 안전한 변환
    if msg_ptr.is_null() || sig_ptr.is_null() {
        return false;
    }

    unsafe {
        let msg = std::slice::from_raw_parts(msg_ptr, msg_len);
        let sig = std::slice::from_raw_parts(sig_ptr, sig_len);
        verify(msg, sig).unwrap_or(false)
    }
}
