    h := hashPool.Get().(hash.Hash)
    defer func() {
        h.Reset()
        hashPool.Put(h)
    }()

    hkdf := hkdf.New(func() hash.Hash { return h }, seed, salt, info)
    _, err := io.ReadFull(hkdf, out)
    return err
