        agentFeedback[serverAgent].push(Feedback({
            taskId: taskId,
            clientAgent: msg.sender,
            serverAgent: serverAgent,
            dataHash: dataHash,
            rating: rating,
            timestamp: block.timestamp
        }));
    }
}
