    // 4. JWK 형식으로도 저장
    jwkExporter := formats.NewJWKExporter()
    jwkData, _ := jwkExporter.ExportPublic(kp, sagecrypto.KeyFormatJWK)
    os.WriteFile("agent-key.jwk", jwkData, 0644)
    fmt.Println("Saved public key to agent-key.jwk")
}
