// 읽기 전용 호출 (call)
func (c *EthereumClient) call(
    method string,
    result interface{},
    args ...interface{},
) error {
    // ABI 인코딩
    input, err := c.contract.Abi.Pack(method, args...)
    if err != nil {
        return fmt.Errorf("failed to pack args: %w", err)
    }

    // eth_call 실행
    msg := ethereum.CallMsg{
        To:   &c.contractAddr,
        Data: input,
    }

    output, err := c.client.CallContract(
        context.Background(),
        msg,
        nil,  // latest block
    )
    if err != nil {
        return fmt.Errorf("call failed: %w", err)
    }

    // ABI 디코딩
    err = c.contract.Abi.UnpackIntoInterface(result, method, output)
    if err != nil {
        return fmt.Errorf("failed to unpack result: %w", err)
    }

    return nil
}

// 트랜잭션 전송 (sendTransaction)
func (c *EthereumClient) transact(
    method string,
    args ...interface{},
) (*types.Transaction, error) {
    // ABI 인코딩
    input, err := c.contract.Abi.Pack(method, args...)
    if err != nil {
        return nil, fmt.Errorf("failed to pack args: %w", err)
    }

    // Nonce 가져오기
    nonce, err := c.client.PendingNonceAt(
        context.Background(),
        c.txOpts.From,
    )
    if err != nil {
        return nil, fmt.Errorf("failed to get nonce: %w", err)
    }

    // 가스 추정
    gasLimit, err := c.client.EstimateGas(context.Background(), ethereum.CallMsg{
        From: c.txOpts.From,
        To:   &c.contractAddr,
        Data: input,
    })
    if err != nil {
        return nil, fmt.Errorf("failed to estimate gas: %w", err)
    }

    // 트랜잭션 생성
    tx := types.NewTransaction(
        nonce,
        c.contractAddr,
        big.NewInt(0),  // value
        gasLimit,
        c.gasPrice,
        input,
    )

    // 서명
    signedTx, err := c.txOpts.Signer(c.txOpts.From, tx)
    if err != nil {
        return nil, fmt.Errorf("failed to sign tx: %w", err)
    }

    // 전송
    err = c.client.SendTransaction(context.Background(), signedTx)
    if err != nil {
        return nil, fmt.Errorf("failed to send tx: %w", err)
    }

    return signedTx, nil
}
