```go
// session/manager.go

func (m *Manager) cleanupLoop() {
    for {
        select {
        case <-m.cleanupTicker.C:
            m.CleanupExpired()
        case <-m.stopCleanup:
            m.cleanupTicker.Stop()
            return
        }
    }
}

func (m *Manager) CleanupExpired() {
    m.mu.Lock()
    defer m.mu.Unlock()

    now := time.Now()
    var expired []string

    // 만료된 세션 찾기
    for sessID, sess := range m.sessions {
        if sess.IsExpired() {
            expired = append(expired, sessID)
        }
    }

    // 제거
    for _, sessID := range expired {
        sess := m.sessions[sessID]

        // 안전한 키 삭제
        sess.Close()

        // 맵에서 제거
        delete(m.sessions, sessID)

        // KeyID 바인딩도 제거
        for keyID, sid := range m.keyIDs {
            if sid == sessID {
                delete(m.keyIDs, keyID)
            }
        }

        log.Info("session cleaned up",
            "id", sessID,
            "reason", "expired")
    }

    if len(expired) > 0 {
        log.Info("cleanup completed", "removed", len(expired))
    }
}

// 강제 제거
func (m *Manager) Remove(sessionID string) error {
    m.mu.Lock()
    defer m.mu.Unlock()

    sess, exists := m.sessions[sessionID]
    if !exists {
        return fmt.Errorf("session not found")
    }

    // 안전한 키 삭제
    sess.Close()

    // 제거
    delete(m.sessions, sessionID)

    // KeyID 바인딩 제거
    for keyID, sid := range m.keyIDs {
        if sid == sessionID {
            delete(m.keyIDs, keyID)
        }
    }

    log.Info("session removed", "id", sessionID)

    return nil
}

// 서버 종료 시
func (m *Manager) Shutdown() {
    close(m.stopCleanup)

    m.mu.Lock()
    defer m.mu.Unlock()

    // 모든 세션 정리
    for _, sess := range m.sessions {
        sess.Close()
    }

    m.sessions = nil
    m.keyIDs = nil
}
