// OnRequest: 요청 수신 시
func (h *MyEventHandler) OnRequest(
    ctx context.Context,
    contextID string,
    req RequestMessage,
    peerPub crypto.PublicKey,
) error {
    log.Info("request received", "context", contextID)

    // 임시 키는 이미 AskEphemeral에서 생성됨
    // 여기서는 추가 검증이나 로깅만

