// session/session.go

// Close: 세션 종료 시 모든 키 삭제
func (s *SecureSession) Close() error {
    s.closed = true

    // 모든 키를 0으로 덮어쓰기 (보안 삭제)
    zeroBytes := func(b []byte) {
        if b != nil {
            for i := range b {
                b[i] = 0
            }
        }
    }

    zeroBytes(s.encryptKey)
    zeroBytes(s.signingKey)
    zeroBytes(s.sessionSeed)
    zeroBytes(s.outKey)
    zeroBytes(s.inKey)
    zeroBytes(s.outSign)
    zeroBytes(s.inSign)

    // AEAD 인스턴스는 GC가 처리
    s.aead = nil
    s.aeadOut = nil
    s.aeadIn = nil

    return nil
}

