            throw new Error('MetaMask not installed');
        }

        await window.ethereum.request({ method: 'eth_requestAccounts' });
        const provider = new ethers.BrowserProvider(window.ethereum);
        return provider.getSigner();
    }

    // 에이전트 조회
    async getAgent(did: string) {
        const agent = await this.contract.getAgentByDID(did);
        return {
            name: agent.name,
            description: agent.description,
            endpoint: agent.endpoint,
            active: agent.active,
            registeredAt: new Date(agent.registeredAt.toNumber() * 1000)
        };
    }

    // 에이전트 등록 (MetaMask 사용)
    async registerAgent(params: {
        did: string;
        name: string;
        description: string;
        endpoint: string;
        publicKey: Uint8Array;
        capabilities: string;
        signature: Uint8Array;
    }) {
        const signer = await this.connectWallet();
        const contractWithSigner = this.contract.connect(signer);

        const tx = await contractWithSigner.registerAgent(
            params.did,
            params.name,
            params.description,
            params.endpoint,
            params.publicKey,
            params.capabilities,
            params.signature
        );

        console.log('Transaction sent:', tx.hash);

