type MessageBatcher struct {
    messages chan *Message
    flush    chan struct{}

    batchSize     int
    flushInterval time.Duration
}

func (b *MessageBatcher) Start() {
    ticker := time.NewTicker(b.flushInterval)
    defer ticker.Stop()

    batch := make([]*Message, 0, b.batchSize)

    for {
        select {
        case msg := <-b.messages:
            batch = append(batch, msg)

            if len(batch) >= b.batchSize {
                b.sendBatch(batch)
                batch = batch[:0]
            }

        case <-ticker.C:
            if len(batch) > 0 {
                b.sendBatch(batch)
                batch = batch[:0]
            }

        case <-b.flush:
            if len(batch) > 0 {
                b.sendBatch(batch)
                batch = batch[:0]
            }
        }
    }
}

