func (a *AuditLogger) LogHandshake(event string, did string, success bool, metadata map[string]interface{}) {
    fields := []zap.Field{
        zap.String("event", event),
        zap.String("peer_did", did),
        zap.Bool("success", success),
        zap.Time("timestamp", time.Now()),
    }

